import { PoolClient } from "pg";
import { pool } from "../../config/database";
import {
  ParentInvitation,
  StudentParentLink,
  ConnectedChildInfo,
  LinkedParentInfo,
  ChildOverviewDTO,
  ChildAssessmentSummary,
  ChildReportSummary,
  ParentReportItemDTO,
  ParentReportDetailDTO,
} from "./parent.types";
import { AppError } from "../../common/errors/app-error";
import { logger } from "../../common/utils/logger";

export class ParentRepository {
  /**
   * Initializes PostgreSQL schema for Parent Connect:
   * 1. parent_invitations (temporary token generated by student)
   * 2. student_parent_links (permanent verified relationship)
   */
  async initSchema(client?: PoolClient): Promise<void> {
    const db = client || pool;
    const query = `
      -- 1. Parent Invitations Table
      CREATE TABLE IF NOT EXISTS parent_invitations (
        id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
        student_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        invite_code VARCHAR(50) UNIQUE NOT NULL,
        status VARCHAR(50) NOT NULL DEFAULT 'ACTIVE',
        expires_at TIMESTAMPTZ NOT NULL,
        used_at TIMESTAMPTZ NULL,
        used_by_parent_id UUID NULL REFERENCES users(id) ON DELETE SET NULL,
        created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
      );

      -- 2. Student-Parent Links Table
      CREATE TABLE IF NOT EXISTS student_parent_links (
        id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
        parent_user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        student_user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
        relationship_type VARCHAR(50) NOT NULL DEFAULT 'PARENT',
        link_status VARCHAR(50) NOT NULL DEFAULT 'ACTIVE',
        link_method VARCHAR(50) NOT NULL DEFAULT 'INVITATION_CODE',
        invitation_id UUID NULL REFERENCES parent_invitations(id) ON DELETE SET NULL,
        verified_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
        created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
        updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
        UNIQUE(parent_user_id, student_user_id)
      );

      -- Migration: Add invitation_id if table already exists
      ALTER TABLE student_parent_links ADD COLUMN IF NOT EXISTS invitation_id UUID REFERENCES parent_invitations(id) ON DELETE SET NULL;

      -- Indexes for parent_invitations
      CREATE UNIQUE INDEX IF NOT EXISTS idx_parent_invitations_code ON parent_invitations(invite_code);
      CREATE INDEX IF NOT EXISTS idx_parent_invitations_student ON parent_invitations(student_id);
      CREATE INDEX IF NOT EXISTS idx_parent_invitations_status ON parent_invitations(status);
      CREATE INDEX IF NOT EXISTS idx_parent_invitations_parent ON parent_invitations(used_by_parent_id);

      -- Indexes for student_parent_links
      CREATE INDEX IF NOT EXISTS idx_student_parent_links_parent ON student_parent_links(parent_user_id);
      CREATE INDEX IF NOT EXISTS idx_student_parent_links_student ON student_parent_links(student_user_id);
      CREATE INDEX IF NOT EXISTS idx_student_parent_links_status ON student_parent_links(link_status);
      CREATE INDEX IF NOT EXISTS idx_student_parent_links_invitation ON student_parent_links(invitation_id);
    `;

    await db.query(query);
    logger.info("📦 Parent Connect database schema (parent_invitations & student_parent_links) verified.");
  }

  /**
   * Inserts a new parent invitation code record.
   */
  async createInvitation(
    data: { studentId: string; inviteCode: string; expiresAt: Date },
    client?: PoolClient
  ): Promise<ParentInvitation> {
    const db = client || pool;
    const query = `
      INSERT INTO parent_invitations (
        student_id, invite_code, status, expires_at, created_at
      )
      VALUES ($1, $2, 'ACTIVE', $3, NOW())
      RETURNING 
        id, 
        student_id AS "studentId", 
        student_id, 
        invite_code AS "inviteCode", 
        invite_code, 
        status, 
        expires_at AS "expiresAt", 
        expires_at, 
        used_at AS "usedAt", 
        used_at, 
        used_by_parent_id AS "usedByParentId", 
        used_by_parent_id, 
        created_at AS "createdAt", 
        created_at
    `;
    const res = await db.query(query, [
      data.studentId,
      data.inviteCode,
      data.expiresAt,
    ]);
    return res.rows[0];
  }

  /**
   * Finds an invitation by its exact code.
   */
  async findInvitationByCode(
    inviteCode: string,
    client?: PoolClient
  ): Promise<ParentInvitation | null> {
    const db = client || pool;
    const query = `
      SELECT 
        id, 
        student_id AS "studentId", 
        student_id, 
        invite_code AS "inviteCode", 
        invite_code, 
        status, 
        expires_at AS "expiresAt", 
        expires_at, 
        used_at AS "usedAt", 
        used_at, 
        used_by_parent_id AS "usedByParentId", 
        used_by_parent_id, 
        created_at AS "createdAt", 
        created_at
      FROM parent_invitations
      WHERE UPPER(TRIM(invite_code)) = UPPER(TRIM($1))
      LIMIT 1
    `;
    const res = await db.query(query, [inviteCode]);
    return res.rows[0] || null;
  }

  /**
   * Finds active (unexpired, status=ACTIVE) invitation for a student.
   */
  async findActiveInvitationByStudentId(
    studentId: string,
    client?: PoolClient
  ): Promise<ParentInvitation | null> {
    const db = client || pool;
    const query = `
      SELECT 
        id, 
        student_id AS "studentId", 
        student_id, 
        invite_code AS "inviteCode", 
        invite_code, 
        status, 
        expires_at AS "expiresAt", 
        expires_at, 
        used_at AS "usedAt", 
        used_at, 
        used_by_parent_id AS "usedByParentId", 
        used_by_parent_id, 
        created_at AS "createdAt", 
        created_at
      FROM parent_invitations
      WHERE student_id = $1
        AND status = 'ACTIVE'
        AND expires_at > NOW()
      ORDER BY created_at DESC
      LIMIT 1
    `;
    const res = await db.query(query, [studentId]);
    return res.rows[0] || null;
  }

  /**
   * Revokes all active invitations for a student.
   */
  async revokeActiveInvitationsForStudent(
    studentId: string,
    client?: PoolClient
  ): Promise<void> {
    const db = client || pool;
    const query = `
      UPDATE parent_invitations
      SET status = 'REVOKED'
      WHERE student_id = $1
        AND status = 'ACTIVE'
    `;
    await db.query(query, [studentId]);
  }

  /**
   * Revokes an invitation by code for a given student.
   */
  async revokeInvitationByCode(
    studentId: string,
    inviteCode: string,
    client?: PoolClient
  ): Promise<boolean> {
    const db = client || pool;
    const query = `
      UPDATE parent_invitations
      SET status = 'REVOKED'
      WHERE student_id = $1
        AND UPPER(TRIM(invite_code)) = UPPER(TRIM($2))
        AND status = 'ACTIVE'
      RETURNING id
    `;
    const res = await db.query(query, [studentId, inviteCode]);
    return (res.rowCount ?? 0) > 0;
  }

  /**
   * Retrieves strictly sanitized, safe student metadata for invitation preview.
   * NEVER returns email, phone, assessment scores, or psychological notes.
   */
  async findSafeStudentInfo(
    studentId: string,
    client?: PoolClient
  ): Promise<{
    id: string;
    firstName: string;
    gradeLevel: string | null;
    educationStage: string | null;
    schoolName: string | null;
  } | null> {
    const db = client || pool;
    const query = `
      SELECT 
        u.id,
        u.first_name AS "firstName",
        COALESCE(pp.grade_level, sp.grade_level) AS "gradeLevel",
        COALESCE(pp.education_stage, sp.education_stage) AS "educationStage",
        COALESCE(pp.school_name, sp.school_name) AS "schoolName"
      FROM users u
      LEFT JOIN participant_profiles pp ON pp.user_id = u.id
      LEFT JOIN student_profiles sp ON sp.user_id = u.id
      WHERE u.id = $1
      LIMIT 1
    `;
    const res = await db.query(query, [studentId]);
    return res.rows[0] || null;
  }

  /**
   * Finds an existing student-parent link record.
   */
  async findLink(
    parentId: string,
    studentId: string,
    client?: PoolClient
  ): Promise<StudentParentLink | null> {
    const db = client || pool;
    const query = `
      SELECT id, parent_user_id, student_user_id, relationship_type, link_status, link_method, verified_at, created_at, updated_at
      FROM student_parent_links
      WHERE parent_user_id = $1 AND student_user_id = $2
      LIMIT 1
    `;
    const res = await db.query(query, [parentId, studentId]);
    return res.rows[0] || null;
  }

  /**
   * Checks if an active relationship exists between a parent and student.
   */
  async isParentOfStudent(
    parentId: string,
    studentId: string,
    client?: PoolClient
  ): Promise<boolean> {
    const db = client || pool;
    const query = `
      SELECT id
      FROM student_parent_links
      WHERE parent_user_id = $1
        AND student_user_id = $2
        AND link_status = 'ACTIVE'
      LIMIT 1
    `;
    const res = await db.query(query, [parentId, studentId]);
    return (res.rowCount ?? 0) > 0;
  }

  /**
   * Fetches all connected active children for a given parent.
   */
  async findConnectedChildren(
    parentId: string,
    client?: PoolClient
  ): Promise<ConnectedChildInfo[]> {
    const db = client || pool;
    const query = `
      SELECT 
        spl.id AS "linkId",
        u.id AS "studentId",
        u.id AS "id",
        TRIM(CONCAT(u.first_name, ' ', u.last_name)) AS "name",
        u.first_name AS "firstName",
        u.last_name AS "lastName",
        EXTRACT(YEAR FROM AGE(COALESCE(pp.date_of_birth, sp.date_of_birth)))::INT AS "age",
        TO_CHAR(COALESCE(pp.date_of_birth, sp.date_of_birth), 'YYYY-MM-DD') AS "dateOfBirth",
        COALESCE(pp.grade_level, sp.grade_level) AS "grade",
        COALESCE(pp.grade_level, sp.grade_level) AS "gradeLevel",
        COALESCE(pp.education_stage, sp.education_stage) AS "educationStage",
        COALESCE(pp.school_name, sp.school_name) AS "school",
        COALESCE(pp.school_name, sp.school_name) AS "schoolName",
        COALESCE(pp.curriculum_or_board, sp.curriculum_or_board) AS "curriculumOrBoard",
        spl.relationship_type AS "relationship",
        spl.relationship_type AS "relationshipType",
        spl.link_status AS "linkStatus",
        spl.link_status AS "status",
        spl.verified_at AS "verifiedAt",
        spl.created_at AS "connectedAt",
        COALESCE((
          SELECT COUNT(DISTINCT ar.assessment_code)::INT
          FROM assessment_results ar
          WHERE ar.participant_id = u.id
        ), 0) AS "completedAssessmentsCount"
      FROM student_parent_links spl
      INNER JOIN users u ON u.id = spl.student_user_id
      LEFT JOIN participant_profiles pp ON pp.user_id = u.id
      LEFT JOIN student_profiles sp ON sp.user_id = u.id
      WHERE spl.parent_user_id = $1
        AND spl.link_status = 'ACTIVE'
      ORDER BY spl.created_at DESC
    `;
    const res = await db.query(query, [parentId]);
    return res.rows.map((row) => ({
      ...row,
      assessmentProgress: {
        completed: row.completedAssessmentsCount || 0,
        total: 6,
      },
    }));
  }

  /**
   * Fetches all connected active parents for a given student.
   */
  async findLinkedParentsForStudent(
    studentId: string,
    client?: PoolClient
  ): Promise<LinkedParentInfo[]> {
    const db = client || pool;
    const query = `
      SELECT 
        spl.id AS "linkId",
        u.id AS "parentId",
        u.first_name AS "firstName",
        u.last_name AS "lastName",
        u.email,
        spl.relationship_type AS "relationshipType",
        spl.link_status AS "linkStatus",
        spl.verified_at AS "verifiedAt",
        spl.created_at AS "connectedAt"
      FROM student_parent_links spl
      INNER JOIN users u ON u.id = spl.parent_user_id
      WHERE spl.student_user_id = $1
        AND spl.link_status = 'ACTIVE'
      ORDER BY spl.created_at DESC
    `;
    const res = await db.query(query, [studentId]);
    return res.rows;
  }

  /**
   * Revokes a student-parent link if the requesting user is either the student or parent.
   */
  async revokeLink(
    linkId: string,
    userId: string,
    client?: PoolClient
  ): Promise<boolean> {
    const db = client || pool;
    const query = `
      UPDATE student_parent_links
      SET link_status = 'REVOKED', updated_at = NOW()
      WHERE id = $1
        AND (parent_user_id = $2 OR student_user_id = $2)
        AND link_status = 'ACTIVE'
      RETURNING id
    `;
    const res = await db.query(query, [linkId, userId]);
    return (res.rowCount ?? 0) > 0;
  }

  /**
   * Retrieves child overview, assessment summaries, reports, and counselling stats.
   */
  async getChildOverviewData(
    studentId: string,
    parentId: string,
    client?: PoolClient
  ): Promise<ChildOverviewDTO | null> {
    const db = client || pool;

    // 1. Fetch link info
    const linkQuery = `
      SELECT id, relationship_type, link_status, verified_at
      FROM student_parent_links
      WHERE parent_user_id = $1 AND student_user_id = $2 AND link_status = 'ACTIVE'
      LIMIT 1
    `;
    const linkRes = await db.query(linkQuery, [parentId, studentId]);
    if (linkRes.rowCount === 0) return null;
    const linkRow = linkRes.rows[0];

    // 2. Fetch student user & profile
    const studentQuery = `
      SELECT 
        u.id,
        u.first_name AS "firstName",
        u.last_name AS "lastName",
        EXTRACT(YEAR FROM AGE(COALESCE(pp.date_of_birth, sp.date_of_birth)))::INT AS "age",
        COALESCE(pp.grade_level, sp.grade_level) AS "gradeLevel",
        COALESCE(pp.education_stage, sp.education_stage) AS "educationStage",
        COALESCE(pp.school_name, sp.school_name) AS "schoolName",
        COALESCE(pp.curriculum_or_board, sp.curriculum_or_board) AS "curriculumOrBoard",
        COALESCE(pp.is_onboarded, sp.is_onboarded, false) AS "isOnboarded"
      FROM users u
      LEFT JOIN participant_profiles pp ON pp.user_id = u.id
      LEFT JOIN student_profiles sp ON sp.user_id = u.id
      WHERE u.id = $1
      LIMIT 1
    `;
    const studentRes = await db.query(studentQuery, [studentId]);
    if (studentRes.rowCount === 0) return null;
    const studentRow = studentRes.rows[0];

    // 3. Fetch assessment attempts & results
    const standardAssessments = [
      { code: "skill_finder", title: "Skill Finder Assessment", category: "Core Aptitude" },
      { code: "stream_finder", title: "Stream Finder Assessment", category: "Academic Pathway" },
      { code: "engineering_branch_finder", title: "Engineering Branch Finder", category: "Specialization" },
      { code: "commerce_career_finder", title: "Commerce Career Finder", category: "Specialization" },
      { code: "humanities_career_finder", title: "Humanities Career Finder", category: "Specialization" },
      { code: "ai_job_risk_finder", title: "AI Job Resilience Assessment", category: "Future Readiness" },
    ];

    const attemptsQuery = `
      SELECT 
        ar.assessment_code,
        ar.id as result_id,
        ar.summary,
        ar.dimension_scores,
        ar.created_at as completed_at,
        aa.status as attempt_status
      FROM assessment_results ar
      LEFT JOIN assessment_attempts aa ON aa.id = ar.attempt_id
      WHERE ar.participant_id = $1
      ORDER BY ar.created_at DESC
    `;
    const attemptsRes = await db.query(attemptsQuery, [studentId]);
    const resultsByCode = new Map<string, any>();
    attemptsRes.rows.forEach((row) => {
      if (!resultsByCode.has(row.assessment_code)) {
        resultsByCode.set(row.assessment_code, row);
      }
    });

    const assessments: ChildAssessmentSummary[] = standardAssessments.map((def) => {
      const match = resultsByCode.get(def.code);
      if (match) {
        let dominantTraits: string[] = [];
        if (match.dimension_scores && typeof match.dimension_scores === "object") {
          dominantTraits = Object.keys(match.dimension_scores).slice(0, 3);
        }
        return {
          assessmentCode: def.code,
          title: def.title,
          category: def.category,
          status: "COMPLETED",
          completedAt: match.completed_at,
          dominantTraits,
          summary: match.summary || "Assessment completed successfully.",
          resultId: match.result_id,
        };
      }
      return {
        assessmentCode: def.code,
        title: def.title,
        category: def.category,
        status: "NOT_STARTED",
        completedAt: null,
      };
    });

    // 4. Fetch reports
    const reportsQuery = `
      SELECT id, report_title as "reportTitle", assessment_code as "assessmentCode",
             language_code as "languageCode", status, generated_at as "generatedAt"
      FROM assessment_reports
      WHERE participant_id = $1
      ORDER BY generated_at DESC
    `;
    const reportsRes = await db.query(reportsQuery, [studentId]);
    const reports: ChildReportSummary[] = reportsRes.rows;

    // 5. Fetch counselling sessions count
    const counsellingQuery = `
      SELECT COUNT(*) as count
      FROM counselling_sessions
      WHERE student_id = $1
    `;
    let counsellingCount = 0;
    try {
      const counsellingRes = await db.query(counsellingQuery, [studentId]);
      counsellingCount = parseInt(counsellingRes.rows[0]?.count || "0", 10);
    } catch {
      counsellingCount = 0;
    }

    return {
      student: {
        id: studentRow.id,
        firstName: studentRow.firstName,
        lastName: studentRow.lastName,
        age: studentRow.age ? parseInt(studentRow.age, 10) : null,
        gradeLevel: studentRow.gradeLevel,
        educationStage: studentRow.educationStage,
        schoolName: studentRow.schoolName,
        curriculumOrBoard: studentRow.curriculumOrBoard,
        isOnboarded: Boolean(studentRow.isOnboarded),
      },
      relationship: {
        linkId: linkRow.id,
        relationshipType: linkRow.relationship_type,
        linkStatus: linkRow.link_status,
        verifiedAt: linkRow.verified_at,
      },
      assessments,
      reports,
      counsellingSessionsCount: counsellingCount,
    };
  }

  /**
   * Fetches all assessment reports for all connected children of a parent (optionally filtered by studentId).
   */
  async getParentReports(
    parentId: string,
    studentId?: string,
    client?: PoolClient
  ): Promise<ParentReportItemDTO[]> {
    const db = client || pool;
    const query = `
      SELECT 
        r.id,
        r.assessment_result_id AS "assessmentResultId",
        r.participant_id AS "studentId",
        TRIM(CONCAT(u.first_name, ' ', u.last_name)) AS "studentName",
        u.first_name AS "studentFirstName",
        u.last_name AS "studentLastName",
        COALESCE(pp.grade_level, sp.grade_level) AS "studentGrade",
        COALESCE(pp.school_name, sp.school_name) AS "studentSchool",
        r.assessment_code AS "assessmentCode",
        r.report_title AS "reportTitle",
        r.profile_archetype AS "profileArchetype",
        r.language_code AS "languageCode",
        r.status,
        r.generated_at AS "generatedAt"
      FROM assessment_reports r
      INNER JOIN student_parent_links spl ON spl.student_user_id = r.participant_id
      INNER JOIN users u ON u.id = r.participant_id
      LEFT JOIN participant_profiles pp ON pp.user_id = u.id
      LEFT JOIN student_profiles sp ON sp.user_id = u.id
      WHERE spl.parent_user_id = $1
        AND spl.link_status = 'ACTIVE'
        AND ($2::uuid IS NULL OR r.participant_id = $2::uuid)
      ORDER BY r.generated_at DESC
    `;
    const res = await db.query(query, [parentId, studentId || null]);
    return res.rows;
  }

  /**
   * Fetches full assessment report details for a parent, verifying that the report belongs to a connected child.
   */
  async getParentReportById(
    parentId: string,
    reportId: string,
    client?: PoolClient
  ): Promise<ParentReportDetailDTO | null> {
    if (!reportId || !/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(reportId)) {
      return null;
    }
    const db = client || pool;
    const query = `
      SELECT 
        r.id,
        r.assessment_result_id AS "assessmentResultId",
        r.participant_id AS "studentId",
        TRIM(CONCAT(u.first_name, ' ', u.last_name)) AS "studentName",
        u.first_name AS "studentFirstName",
        u.last_name AS "studentLastName",
        u.email AS "studentEmail",
        COALESCE(pp.grade_level, sp.grade_level) AS "studentGrade",
        COALESCE(pp.school_name, sp.school_name) AS "studentSchool",
        COALESCE(pp.education_stage, sp.education_stage) AS "studentEducationStage",
        COALESCE(pp.curriculum_or_board, sp.curriculum_or_board) AS "studentCurriculum",
        EXTRACT(YEAR FROM AGE(COALESCE(pp.date_of_birth, sp.date_of_birth)))::INT AS "studentAge",
        r.assessment_code AS "assessmentCode",
        r.report_title AS "reportTitle",
        r.profile_archetype AS "profileArchetype",
        r.language_code AS "languageCode",
        r.status,
        r.report_data AS "reportData",
        r.file_path AS "filePath",
        r.generated_at AS "generatedAt"
      FROM assessment_reports r
      INNER JOIN student_parent_links spl ON spl.student_user_id = r.participant_id
      INNER JOIN users u ON u.id = r.participant_id
      LEFT JOIN participant_profiles pp ON pp.user_id = u.id
      LEFT JOIN student_profiles sp ON sp.user_id = u.id
      WHERE (r.id = $1 OR r.assessment_result_id = $1)
        AND spl.parent_user_id = $2
        AND spl.link_status = 'ACTIVE'
      LIMIT 1
    `;
    const res = await db.query(query, [reportId, parentId]);
    if (res.rowCount === 0) return null;
    const row = res.rows[0];
    return {
      ...row,
      reportData: typeof row.reportData === "string" ? JSON.parse(row.reportData) : row.reportData,
    };
  }

  /**
   * Atomically redeems an invitation code using a PostgreSQL transaction.
   */
  async redeemInvitationTx(
    parentId: string,
    inviteCode: string,
    studentEmail: string,
    relationshipType = "PARENT"
  ): Promise<{ link: StudentParentLink; student: { id: string; firstName: string; lastName: string } }> {
    const client = await pool.connect();
    try {
      await client.query("BEGIN");

      const normalizedCode = inviteCode.trim().toUpperCase();

      // 1. Lock and fetch invitation row
      const invRes = await client.query(
        `SELECT id, student_id, invite_code, status, expires_at, used_at, used_by_parent_id, created_at
         FROM parent_invitations
         WHERE UPPER(TRIM(invite_code)) = $1
         FOR UPDATE`,
        [normalizedCode]
      );

      if (invRes.rowCount === 0) {
        throw AppError.notFound(
          "Invalid invitation code. Please check the code and try again.",
          "INVITATION_NOT_FOUND"
        );
      }

      const invitation = invRes.rows[0];

      // 2. Validate invitation status
      if (invitation.status === "USED") {
        throw AppError.badRequest(
          "This invitation code has already been used.",
          "INVITATION_ALREADY_USED"
        );
      }

      if (invitation.status === "REVOKED") {
        throw AppError.badRequest(
          "This invitation code has been revoked by the student.",
          "INVITATION_REVOKED"
        );
      }

      if (invitation.status !== "ACTIVE") {
        throw AppError.badRequest(
          "This invitation is no longer active.",
          "INVITATION_INACTIVE"
        );
      }

      // Check expiration
      if (new Date(invitation.expires_at).getTime() <= Date.now()) {
        await client.query(
          `UPDATE parent_invitations SET status = 'EXPIRED' WHERE id = $1`,
          [invitation.id]
        );
        throw AppError.badRequest(
          "This invitation code has expired. Please ask the student to generate a new invitation code.",
          "INVITATION_EXPIRED"
        );
      }

      // 3. Self-linking guard (A student cannot be their own parent)
      if (invitation.student_id === parentId) {
        throw AppError.badRequest(
          "A student cannot redeem their own parent invitation code.",
          "INVALID_RELATIONSHIP"
        );
      }

      // 4. Fetch student user to ensure active existence & verify registered email
      const studentUserRes = await client.query(
        `SELECT id, email, first_name, last_name, status FROM users WHERE id = $1`,
        [invitation.student_id]
      );
      if (studentUserRes.rowCount === 0) {
        throw AppError.notFound("Associated student account could not be found.", "STUDENT_NOT_FOUND");
      }
      const studentUser = studentUserRes.rows[0];

      // 4b. Strict Student Email Verification
      const normalizedEnteredEmail = (studentEmail || "").trim().toLowerCase();
      const normalizedStudentEmail = (studentUser.email || "").trim().toLowerCase();

      if (!normalizedEnteredEmail || normalizedEnteredEmail !== normalizedStudentEmail) {
        throw AppError.badRequest(
          "The student email does not match the registered account.",
          "STUDENT_EMAIL_MISMATCH"
        );
      }

      // 5. Check if link already exists between parent and student
      const linkRes = await client.query(
        `SELECT id, link_status FROM student_parent_links WHERE parent_user_id = $1 AND student_user_id = $2`,
        [parentId, invitation.student_id]
      );

      let savedLink: StudentParentLink;

      if (linkRes.rowCount && linkRes.rowCount > 0) {
        const existingLink = linkRes.rows[0];
        if (existingLink.link_status === "ACTIVE") {
          throw AppError.conflict(
            "You are already linked to this student.",
            "RELATIONSHIP_ALREADY_EXISTS"
          );
        }

        // Reactivate link if previously revoked or pending
        const updateLinkRes = await client.query(
          `UPDATE student_parent_links
           SET link_status = 'ACTIVE',
               relationship_type = $1,
               link_method = 'INVITATION_CODE',
               invitation_id = $2,
               verified_at = NOW(),
               updated_at = NOW()
           WHERE id = $3
           RETURNING id, parent_user_id, student_user_id, relationship_type, link_status, link_method, invitation_id, verified_at, created_at, updated_at`,
          [relationshipType || "PARENT", invitation.id, existingLink.id]
        );
        savedLink = updateLinkRes.rows[0];
      } else {
        // Insert new verified link with invitation_id
        const insertLinkRes = await client.query(
          `INSERT INTO student_parent_links (
             parent_user_id, student_user_id, relationship_type, link_status, link_method, invitation_id, verified_at, created_at, updated_at
           )
           VALUES ($1, $2, $3, 'ACTIVE', 'INVITATION_CODE', $4, NOW(), NOW(), NOW())
           RETURNING id, parent_user_id, student_user_id, relationship_type, link_status, link_method, invitation_id, verified_at, created_at, updated_at`,
          [parentId, invitation.student_id, relationshipType || "PARENT", invitation.id]
        );
        savedLink = insertLinkRes.rows[0];
      }

      // 6. Mark invitation as USED
      await client.query(
        `UPDATE parent_invitations
         SET status = 'USED',
             used_at = NOW(),
             used_by_parent_id = $1
         WHERE id = $2`,
        [parentId, invitation.id]
      );

      await client.query("COMMIT");

      return {
        link: savedLink,
        student: {
          id: studentUser.id,
          firstName: studentUser.first_name,
          lastName: studentUser.last_name,
        },
      };
    } catch (err) {
      await client.query("ROLLBACK");
      throw err;
    } finally {
      client.release();
    }
  }
}

export const parentRepository = new ParentRepository();
